INSERT INTO `vs_drama_video` VALUES (1,1,'总裁夫人惹不起','{\"en\": \"The CEO\'s Wife Is Not to Be Trifled With\", \"zh-CN\": \"总裁夫人惹不起\", \"zh-TW\": \"總裁夫人惹不起\"}','https://oss.reelchain.art/20250620/译制剧/Untouchable CEO\'s Wife The Cover-up Unveiled/1.png','https://oss.reelchain.art/20250620/译制剧/Untouchable CEO\'s Wife The Cover-up Unveiled/1.png',76,0,'0.0',1,1,'1,3','','她以为嫁入豪门是幸福开始，却不知暗流涌动……','{\"en\": \"She thought marrying into a wealthy family was the start of happiness, not knowing dark currents lurked beneath...\", \"zh-CN\": \"她以为嫁入豪门是幸福开始，却不知暗流涌动……\", \"zh-TW\": \"她以為嫁入豪門是幸福開始，卻不知暗流湧動……\"}',NULL,'','','中国大陆','','普通话',39941,0,11,0,0,0,0,0.00,1,3,'local','',10,'','2026-05-13 22:50:16','2026-05-17 20:55:38',NULL),(2,1,'永不属于你','{\"en\": \"Never Yours\", \"zh-CN\": \"永不属于你\", \"zh-TW\": \"永不屬於你\"}','https://oss.reelchain.art/20250620/译制剧/Never to be yours/1.png','https://oss.reelchain.art/20250620/译制剧/Never to be yours/1.png',80,0,'0.0',1,1,'1,3','','两个人的爱，一个人的执念，终究敌不过命运的捉弄。','{\"en\": \"Two people\'s love, one person\'s obsession — in the end, no match for fate\'s cruel game.\", \"zh-CN\": \"两个人的爱，一个人的执念，终究敌不过命运的捉弄。\", \"zh-TW\": \"兩個人的愛，一個人的執念，終究敵不過命運的捉弄。\"}',NULL,'','','中国大陆','','普通话',29913,0,1,0,0,7,0,0.00,1,3,'local','',9,'','2026-05-13 22:50:16','2026-05-17 02:39:36',NULL),(3,1,'从离婚开始','{\"en\": \"Starting Over After Divorce\", \"zh-CN\": \"从离婚开始\", \"zh-TW\": \"從離婚開始\"}','https://oss.reelchain.art/20251119/8d4fe5ba651846c28ef3b857c81ca1a6.png','https://oss.reelchain.art/20251119/8d4fe5ba651846c28ef3b857c81ca1a6.png',77,0,'0.0',1,1,'1,6','','离婚才是她重新做自己的第一步，谁说结局一定是悲剧？','{\"en\": \"Divorce is her first step to reclaiming herself — who says it has to end in tragedy?\", \"zh-CN\": \"离婚才是她重新做自己的第一步，谁说结局一定是悲剧？\", \"zh-TW\": \"離婚才是她重新做自己的第一步，誰說結局一定是悲劇？\"}',NULL,'','','中国大陆','','普通话',26745,0,1,0,0,0,0,0.00,1,3,'local','',8,'','2026-05-13 22:50:16','2026-05-17 21:10:00',NULL),(4,1,'旧爱化作新情','{\"en\": \"Old Love, New Feelings\", \"zh-CN\": \"旧爱化作新情\", \"zh-TW\": \"舊愛化作新情\"}','https://oss.reelchain.art/20251119/ec305d87076a47be88df2483d5eba31d.jpg','https://oss.reelchain.art/20251119/ec305d87076a47be88df2483d5eba31d.jpg',71,0,'0.0',1,1,'3,1','','旧日情深化不开，重逢之后，究竟是续情还是放手？','{\"en\": \"Old feelings run too deep to fade — after reuniting, will they rekindle or let go?\", \"zh-CN\": \"旧日情深化不开，重逢之后，究竟是续情还是放手？\", \"zh-TW\": \"舊日情深化不開，重逢之後，究竟是續情還是放手？\"}',NULL,'','','中国大陆','','普通话',40985,0,0,0,0,0,0,0.00,1,3,'local','',7,'','2026-05-13 22:50:16','2026-05-17 02:39:26',NULL),(5,1,'爱的倒计时','{\"en\": \"Countdown to Love\", \"zh-CN\": \"爱的倒计时\", \"zh-TW\": \"愛的倒計時\"}','https://oss.reelchain.art/20251119/74242e21068b4306a98c4df737968a4e.png','https://oss.reelchain.art/20251119/74242e21068b4306a98c4df737968a4e.png',69,0,'0.0',1,1,'3','','倒计时开始，她只想在离别前把所有的爱都给他。','{\"en\": \"As the countdown begins, all she wants is to give him every last bit of her love before goodbye.\", \"zh-CN\": \"倒计时开始，她只想在离别前把所有的爱都给他。\", \"zh-TW\": \"倒計時開始，她只想在離別前把所有的愛都給他。\"}',NULL,'','','中国大陆','','普通话',21689,0,0,0,0,0,0,0.00,1,3,'local','',6,'','2026-05-13 22:50:16','2026-05-17 21:10:05',NULL),(6,1,'年轻指挥官的复仇侍女','{\"en\": \"The Young Commander\'s Revenge Maid\", \"zh-CN\": \"年轻指挥官的复仇侍女\", \"zh-TW\": \"年輕指揮官的復仇侍女\"}','https://oss.reelchain.art/20250620/译制剧/The Young Commander\'s Avenging Maid/1.png','https://oss.reelchain.art/20250620/译制剧/The Young Commander\'s Avenging Maid/1.png',74,0,'0.0',1,1,'2','','朝堂风云，刀光剑影，她以侍女身份潜入，只为复仇。','{\"en\": \"Court intrigue, crossed blades — she infiltrates as a maid, all for the sake of revenge.\", \"zh-CN\": \"朝堂风云，刀光剑影，她以侍女身份潜入，只为复仇。\", \"zh-TW\": \"朝堂風雲，刀光劍影，她以侍女身份潛入，只為復仇。\"}',NULL,'','','中国大陆','','普通话',32493,0,0,0,0,0,0,0.00,1,3,'local','',5,'','2026-05-13 22:50:16','2026-05-17 21:10:10',NULL),(7,1,'我真的不是隐世高人','{\"en\": \"I\'m Really Not a Hidden Master\", \"zh-CN\": \"我真的不是隐世高人\", \"zh-TW\": \"我真的不是隱世高人\"}','https://oss.reelchain.art/20250620/译制剧/I\'m Really Not a Reclusive Master/1.png','https://oss.reelchain.art/20250620/译制剧/I\'m Really Not a Reclusive Master/1.png',64,0,'0.0',1,0,'4','','他只想平静生活，奈何这世界非要逼出他真正的实力。','{\"en\": \"All he wants is a peaceful life, but the world keeps forcing out his true power.\", \"zh-CN\": \"他只想平静生活，奈何这世界非要逼出他真正的实力。\", \"zh-TW\": \"他只想平靜生活，奈何這世界非要逼出他真正的實力。\"}',NULL,'','','中国大陆','','普通话',44399,0,0,0,0,0,0,0.00,1,3,'local','',4,'','2026-05-13 22:50:16','2026-05-13 22:50:16',NULL),(8,1,'被宠坏的继承人','{\"en\": \"The Spoiled Heir\", \"zh-CN\": \"被宠坏的继承人\", \"zh-TW\": \"被寵壞的繼承人\"}','https://oss.reelchain.art/20250620/译制剧/Spoiled Substitute Heiress/1.png','https://oss.reelchain.art/20250620/译制剧/Spoiled Substitute Heiress/1.png',71,0,'0.0',1,0,'1,4','','顶级豪门继承人，被宠溺长大，但宠他的人却蓄意已久……','{\"en\": \"The heir to a top-tier family, raised in indulgence — but the one who spoiled him had ulterior motives all along...\", \"zh-CN\": \"顶级豪门继承人，被宠溺长大，但宠他的人却蓄意已久……\", \"zh-TW\": \"頂級豪門繼承人，被寵溺長大，但寵他的人卻蓄意已久……\"}',NULL,'','','中国大陆','','普通话',21513,0,0,0,0,0,0,0.00,1,3,'local','',3,'','2026-05-13 22:50:16','2026-05-13 22:50:16',NULL);
