INSERT INTO `vs_drama_vip` VALUES (1,1,'周卡VIP','{\"en\": \"Weekly VIP\", \"zh-CN\": \"周卡VIP\", \"zh-TW\": \"週卡VIP\"}','','连续包周，畅享全站','{\"en\": \"Enjoy 7 days of VIP privileges. Ad-free streaming and unlimited access to exclusive dramas.\", \"zh-CN\": \"畅享7天VIP特权，全站短剧免广告，专属剧集随心看\", \"zh-TW\": \"暢享7天VIP特權，全站短劇免廣告，專屬劇集隨心看\"}','全站短剧免广告、全集免费观看',7,6.90,9.90,100,'normal','2026-05-11 00:07:49',NULL,NULL),(2,1,'月卡VIP','{\"en\": \"Monthly VIP\", \"zh-CN\": \"月卡VIP\", \"zh-TW\": \"月卡VIP\"}','','连续包月，超值推荐','{\"en\": \"Enjoy 30 days of VIP privileges. Ad-free streaming and unlimited access to exclusive dramas.\", \"zh-CN\": \"畅享30天VIP特权，全站短剧免广告，专属剧集随心看\", \"zh-TW\": \"暢享30天VIP特權，全站短劇免廣告，專屬劇集隨心看\"}','全站短剧免广告、全集免费观看',30,18.00,28.00,90,'normal','2026-05-11 00:07:49',NULL,NULL),(3,1,'季卡VIP','{\"en\": \"Quarterly VIP\", \"zh-CN\": \"季卡VIP\", \"zh-TW\": \"季卡VIP\"}','','连续包季，低至每天2毛','{\"en\": \"Enjoy 90 days of VIP privileges. Ad-free streaming, unlimited dramas, and great value.\", \"zh-CN\": \"畅享90天VIP特权，全站短剧免广告，专属剧集随心看，超值优惠\", \"zh-TW\": \"暢享90天VIP特權，全站短劇免廣告，專屬劇集隨心看，超值優惠\"}','全站短剧免广告、全集免费观看',90,39.00,68.00,80,'normal','2026-05-11 00:07:49',NULL,NULL),(4,1,'年卡VIP','{\"en\": \"Annual VIP\", \"zh-CN\": \"年卡VIP\", \"zh-TW\": \"年卡VIP\"}','','连续包年，最超值','{\"en\": \"Enjoy 365 days of VIP privileges. Best value plan with ad-free streaming and full drama access.\", \"zh-CN\": \"畅享365天VIP特权，全站短剧免广告，专属剧集随心看，最划算之选\", \"zh-TW\": \"暢享365天VIP特權，全站短劇免廣告，專屬劇集隨心看，最划算之選\"}','全站短剧免广告、全集免费观看',365,108.00,198.00,70,'normal','2026-05-11 00:07:49',NULL,NULL),(5,1,'体验卡','{\"en\": \"Trial Card\", \"zh-CN\": \"体验卡\", \"zh-TW\": \"體驗卡\"}','','新用户首充特惠','{\"en\": \"3-day VIP trial. Experience all premium features for free.\", \"zh-CN\": \"3天VIP体验，免费试用全站专属权益\", \"zh-TW\": \"3天VIP體驗，免費試用全站專屬權益\"}','全站短剧免广告、全集免费观看',3,0.90,3.90,110,'normal','2026-05-11 00:07:49',NULL,NULL);
